const hhmm=()=>pad(new Date().getHours())+':'+pad(new Date().getMinutes());
const localIso=()=>{const d=new Date();return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());};
const dateLabel=()=>stamp().split(',')[0];
const thin=t=>{if(t.length<=1500)return t;const k=Math.ceil(t.length/1500);return t.filter((_,i)=>i%k===0||i===t.length-1||t[i][2]===1);};
/* GPS quality rules: ignore coarse fixes, ignore drift while standing still, ignore impossible jumps, and never count or draw a line across a gap */
