const blankCk=()=>({time:hhmm(),name:'',id:'',phone:'',others:[],gear:'Hand line',gearId:'',qty:'',ground:'',origin:'Pate',code:'',action:ACTIONS[0],details:'',seized:false,items:[blankItem()]});
